// TH14 synthetic training aliases (see transcribe/th14/touhou-bullets.ecl).
// Native type 0..23 -> modern same number; 24..42 -> modern +1. Not byte-identical assets.
// This card only fires native type 10 (etSprite(0,10,6)), alias TH14_SHARD at modern row base 512.
const TH14_SHARD: int = 512;

// th14_s6_w03 — TH14 v1.00b st06.ecl.txt
