//   dependency ECir01   :90-124
//   dependency ECir01_at:126-176
// Source frame 0 = first statement of MainSub03 (line 631). Card frame 0 = phase start;
// OPENING_BUFFER keeps the source schedule starting after the shell's 120-frame opening.

const TIME_LIMIT: int = 2324;
const OPENING_BUFFER: int = 120;

// ECir01_at (126-176): fire rounds of one ring each, base angle rotated by the inherited F2.
// Source 155/156: A = pi/2, B = diffI(20,40,50,60). Source 161-163: A += F2 (+1 extra on Easy).
async sub ecir01_at(d: angle) {
    wait(10); // 129
    var rank: int = global(GVAR_RANK);
    var n: int = 4; // 133-140 etCount: E4/N4/H5/L6
    if rank == 2 { n = 5; }
    if rank == 3 { n = 6; }
    var speed: fx = 3fx; // 144-153: E 2.0, N/H/LO 3.0 (layers=1 so speed1 unused)
    if rank == 0 { speed = 2fx; }
    var rounds: int = 20; // 156 diffI($B, 20, 40, 50, 60)
    if rank == 1 { rounds = 40; }
    if rank == 2 { rounds = 50; }
    if rank == 3 { rounds = 60; }
    var wt: int = 3; // 162-171 wait: E8/N4/H3/L3
    if rank == 0 { wt = 8; } else if rank == 1 { wt = 4; }
    var a: angle = 90deg; // 155 %A = 1.570796 (source 143 RANDRAD is overwritten and never fired)
    for r in 0..rounds { // 157/173-174: if ($B--) goto 516
        for i in 0..n { // 159-160 etAngle(0,A,0) + etOn, aim mode 3 ring: A + 2*pi*i/n
            var bi: int = (a as int) + (i * 65536) / n;
            // 154 etEx slot0 type2 a=1 = birth ANIM: animation omitted, spawn retreat kept
            // (position -= 4*velocity, velocity = configured speed; ex-effects ANIM a=1/2).
            _ = fire(TH14_SHARD, 6,
                     $self_x - 4fx * speed * cos(bi as angle),
                     $self_y - 4fx * speed * sin(bi as angle),
                     speed, bi as angle, none, none);
        }
        a = a + d; // 161
        if rank == 0 { a = a + d; } // 162-163 Easy adds F2 twice
        wait(wt); // 172
    }
}

// ECir01 (90-124). F0/F1 are the movePosRelTime target, F2 the per-volley angle step
// (source I0=2 and score/item are entry state / omitted drops, not read in this closure).
async sub ecir01(f0: fx, f1: fx, d: angle) {
    set_invuln(65535);
    set_hurtbox(12fx); // 96 setHurtbox(24,24) -> r=12
    set_hitbox(8fx); // 97 setHitbox(16,16) -> r=8
    set_enemy_flag(ENEMY_NO_BODY, 1); // 101 flagSet(15): 0x2 body gate off while entering
    // 108 movePosRel(160 + RANDF2*32, RANDF2*64): REL layer written at once (two draws, x then y).
    var ux: fx = (rand(65536) - 32768) as fx / 32768;
    var uy: fx = (rand(65536) - 32768) as fx / 32768;
    move_to(0, 160fx + ux * 32fx, 208fx + uy * 64fx, EASE_LINEAR);
    // 109 movePosRelTime(160, mode1 t^2, F0, F1) from the REL value written above.
    move_to(160, f0, 208fx + f1, EASE_QUAD_IN);
    wait(160); // 110
    set_enemy_flag(ENEMY_NO_BODY, 0); // 111 flagClear(15)
    spawn ecir01_at(d); // 114 @ECir01_at() async
    wait(400); // 115
    move_vel(0, aim_player(), 0fx, EASE_LINEAR); // 116 moveVel(%ANGLE_PLAYER, 0)
    move_speed(120, 0.5fx, EASE_LINEAR); // 117 moveSpeedTime(120, mode0, 0.5)
    loop { wait(1000); } // 118-122 goto 860/880: wait(1000) forever
}

